const { withAppBuildGradle } = require('@expo/config-plugins');

/**
 * Removes React Native's `enableBundleCompression` assignment generated by
 * Expo template for SDK 54, which is not supported by the current RN Gradle extension.
 */
module.exports = function withDisableBundleCompressionPatch(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== 'groovy') {
      return config;
    }

    const linePattern = /^\s*enableBundleCompression\s*=.*\r?\n?/m;
    if (linePattern.test(config.modResults.contents)) {
      config.modResults.contents = config.modResults.contents.replace(linePattern, '');
    }

    return config;
  });
};
